def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_m, last_o = history[-1]
    if n == 99:
        return 'D'

    opp_d = 0
    my_d = 0
    cc = 0
    for a, b in history:
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1
        if a == 'C' and b == 'C':
            cc += 1

    recent5 = history[-min(n, 5):]
    r5_opp_d = sum(1 for a, b in recent5 if b == 'D')
    recent10 = history[-min(n, 10):]
    r10_opp_d = sum(1 for a, b in recent10 if b == 'D')

    forgive = 0
    punish = 0
    unprov = 0
    last_forgive = -1
    last_punish = -1
    for i in range(1, n):
        pm, po = history[i - 1]
        cm, co = history[i]
        if co == 'D' and pm == 'C':
            unprov += 1
        if pm == 'D' and po == 'C':
            if co == 'C':
                forgive += 1
                last_forgive = i
            elif co == 'D':
                punish += 1
                last_punish = i

    opp_coop_rate = 1.0 - (opp_d / float(n))

    if opp_coop_rate < 0.45 or (n >= 20 and opp_d > n * 0.60) or r10_opp_d >= 8:
        return 'D'

    if last_o == 'D':
        if n < 10:
            return 'D'

        if last_m == 'D':
            if opp_coop_rate > 0.60 and opp_d <= max(2, n // 4) and r10_opp_d <= 5:
                return 'C'
            return 'D'
        else:
            if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
                if opp_coop_rate > 0.60 and unprov <= max(1, n // 8) and r10_opp_d <= 4:
                    return 'C'
            if opp_coop_rate > 0.85 and opp_d <= max(1, n // 10) and r5_opp_d <= 1:
                return 'C'
            return 'D'

    # last_o == 'C'
    if cc == n and n >= 70:
        if n == 75 and rng.random() < 0.06:
            return 'D'
        if n == 96 and rng.random() < 0.45:
            return 'D'

    if (last_forgive > last_punish and last_forgive >= 0 and
            (n - last_forgive) <= 30 and r10_opp_d <= 1 and opp_coop_rate > 0.60 and
            unprov <= max(1, n // 8)):
        if last_m == 'D':
            if forgive >= 3 and punish == 0 and r10_opp_d == 0:
                return 'D'
            return 'C'
        return 'D'

    return 'C'
